{
  "schemaVersion": 1,
  "id": "parker.drawer",
  "name": "Drawer bar",
  "version": "1.0.0",
  "author": "parker",
  "description": "The stock Omarchy bar plus a drawer button: widgets marked \"drawer\": true in shell.json are tucked into a panel that opens from the button.",
  "kinds": ["bar"],
  "entryPoints": {
    "bar": "DrawerBar.qml"
  }
}

import QtQuick
import Quickshell
import Quickshell.Hyprland
import Quickshell.Io
import qs.Commons

// Drawer bar: a full-bar option that runs the stock Omarchy bar unchanged and
// adds a drawer to it.
//
// Every bar.layout entry marked `"drawer": true` is taken out of the bar and
// shown inside a panel that opens from the drawer button instead. The tucked
// entries stay in their left/center/right sections of shell.json, so they keep
// their settings, still count as "in the bar" for enabled-state checks, and come
// straight back if you switch to the built-in bar again.
//
// The drawer button sits wherever a `{ "id": "parker.drawer" }` entry is placed
// in the layout; without one it is added at the start of the right section.
Item {
  id: root

  // Injected by the shell host (shell.qml configureBar). A third-party bar gets
  // a capability-scoped shell facade and detached config/registry snapshots;
  // the stock bar below runs on exactly those, so it gets no extra access.
  property string omarchyPath: Quickshell.env("OMARCHY_PATH")
  property var shell: null
  property var manifest: null
  property var barWidgetRegistry: null
  property var pluginRegistry: null
  property var barConfig: ({})

  readonly property string pluginId: manifest && manifest.id ? String(manifest.id) : "parker.drawer"
  readonly property string barSource: root.omarchyPath ? Util.fileUrl(root.omarchyPath + "/shell/plugins/bar/Bar.qml") : ""

  // The stock Bar.qml instance.
  readonly property var bar: barLoader.item

  // Scalar bar state the shell reads off `shell.bar`.
  readonly property bool barHidden: bar ? bar.barHidden === true : false
  readonly property int barSize: bar ? bar.barSize : 0
  readonly property string fontFamily: bar ? String(bar.fontFamily || "") : ""
  readonly property string position: bar ? String(bar.position || "top") : "top"
  readonly property bool vertical: position === "left" || position === "right"

  // Tucked entries in bar order (left, center, right). Rebuilt only when the
  // list of widgets changes; settings-only edits go to drawerSettings so the
  // hosted widgets update in place rather than being torn down.
  property var drawerEntries: []
  property var drawerSettings: []
  property string drawerSignature: ""

  // Live drawer buttons, one per monitor.
  property var drawerButtons: []

  // ------------------------------------------------------------ config

  function isTucked(entry) {
    return Util.isPlainObject(entry) && entry.drawer === true
      && String(entry.id || "") !== root.pluginId
  }

  function entrySettings(entry) {
    var copy = {}
    if (!Util.isPlainObject(entry)) return copy
    for (var key in entry) if (key !== "id") copy[key] = entry[key]
    return copy
  }

  // Signature of everything that requires rebuilding a hosted widget: its id
  // and, for custom modules, what it loads or runs.
  function structureKey(entry) {
    return [String(entry.id || ""), String(entry.type || ""), String(entry.source || ""), String(entry.exec || "")]
  }

  function splitConfig(config) {
    var cfg = Util.isPlainObject(config) ? Util.cloneJson(config) : {}
    var layout = Util.isPlainObject(cfg.layout) ? cfg.layout : {}
    var sections = ["left", "center", "right"]
    var tucked = []
    var hasButton = false

    for (var s = 0; s < sections.length; s++) {
      var list = Array.isArray(layout[sections[s]]) ? layout[sections[s]] : []
      var kept = []
      for (var i = 0; i < list.length; i++) {
        var entry = list[i]
        if (typeof entry === "string") entry = { id: entry }
        if (!Util.isPlainObject(entry) || !entry.id) continue
        entry.id = Util.canonicalWidgetId(entry.id)
        if (entry.id === root.pluginId) hasButton = true
        if (root.isTucked(entry)) tucked.push(entry)
        else kept.push(entry)
      }
      layout[sections[s]] = kept
    }

    if (!hasButton) layout.right.unshift({ id: root.pluginId })
    cfg.layout = layout
    return { config: cfg, tucked: tucked }
  }

  function applyConfig() {
    var split = root.splitConfig(root.barConfig)

    var signature = JSON.stringify(split.tucked.map(root.structureKey))
    var settings = split.tucked.map(root.entrySettings)
    if (signature !== root.drawerSignature) {
      root.drawerSignature = signature
      root.drawerSettings = settings
      root.drawerEntries = split.tucked
    } else if (JSON.stringify(settings) !== JSON.stringify(root.drawerSettings)) {
      root.drawerSettings = settings
    }

    if (root.bar) root.bar.barConfig = split.config
  }

  onBarConfigChanged: applyConfig()
  onPluginIdChanged: applyConfig()

  // ---------------------------------------------------- widget registry

  // The registry handed to the stock bar: the host's widget catalogue plus the
  // drawer button. `firstParty` on the button entry only tells Bar.qml to
  // inject itself as the button's `bar`, which the drawer needs in order to host
  // widgets the same way the bar does. It exists only in this private view and
  // grants nothing at the shell level.
  QtObject {
    id: drawerRegistry

    readonly property var upstream: root.barWidgetRegistry
    readonly property var widgets: {
      var base = upstream && upstream.widgets ? upstream.widgets : {}
      var next = {}
      for (var key in base) next[key] = base[key]
      next[root.pluginId] = {
        component: drawerButtonComponent,
        metadata: {
          displayName: "Drawer",
          description: "Opens the panel of tucked-away bar widgets",
          category: "Layout",
          allowMultiple: false,
          pluginId: root.pluginId,
          source: "plugin",
          firstParty: true
        }
      }
      return next
    }
    readonly property int revision: upstream ? upstream.revision : 0

    function metadataFor(id) {
      var entry = widgets[String(id || "")]
      return entry ? entry.metadata : null
    }

    function availableIds() {
      return Object.keys(widgets)
    }

    function has(id) {
      return widgets[String(id || "")] !== undefined
    }
  }

  Component {
    id: drawerButtonComponent

    DrawerButton {
      host: root
    }
  }

  Loader {
    id: barLoader

    active: root.barSource !== ""
    source: root.barSource
    onLoaded: {
      item.omarchyPath = Qt.binding(function() { return root.omarchyPath })
      item.shell = Qt.binding(function() { return root.shell })
      item.manifest = Qt.binding(function() { return root.manifest })
      item.pluginRegistry = Qt.binding(function() { return root.pluginRegistry })
      item.barWidgetRegistry = drawerRegistry
      root.applyConfig()
    }
    onStatusChanged: {
      if (status === Loader.Error) console.warn("parker.drawer: could not load the stock bar from " + root.barSource)
    }
  }

  Component.onCompleted: applyConfig()

  // Hosted widgets register their click targets with the bar like any widget.
  // The bar dispatches clicks on its own slots by mapping into those targets,
  // and that mapping ignores which window a target lives in, so a target inside
  // the drawer panel could catch a click aimed at the bar. Hosted widgets
  // handle their own clicks, so keep them out of the bar's dispatch list.
  Connections {
    target: root.bar
    ignoreUnknownSignals: true

    function onClickTargetsChanged() {
      var targets = root.bar.clickTargets || []
      var kept = targets.filter(function(target) { return !root.drawerOwns(target) })
      if (kept.length !== targets.length) root.bar.clickTargets = kept
    }
  }

  // ------------------------------------------------------------ drawer

  function registerDrawerButton(button) {
    if (!button || drawerButtons.indexOf(button) !== -1) return
    var next = drawerButtons.slice()
    next.push(button)
    drawerButtons = next
  }

  function unregisterDrawerButton(button) {
    drawerButtons = drawerButtons.filter(function(item) { return item !== button })
  }

  function drawerOwns(target) {
    for (var i = 0; i < drawerButtons.length; i++)
      if (drawerButtons[i] && drawerButtons[i].ownsTarget(target)) return true
    return false
  }

  function isTuckedId(id) {
    var key = Util.canonicalWidgetId(id)
    for (var i = 0; i < drawerEntries.length; i++)
      if (String(drawerEntries[i].id) === key) return true
    return false
  }

  // The drawer button on the monitor Hyprland has focused, falling back to any
  // visible one.
  function focusedDrawerButton() {
    var monitor = Hyprland.focusedMonitor
    var focused = monitor ? String(monitor.name || "") : ""
    var fallback = null
    for (var i = 0; i < drawerButtons.length; i++) {
      var button = drawerButtons[i]
      if (!button || !button.visible) continue
      if (focused && button.screenName === focused) return button
      if (!fallback) fallback = button
    }
    return fallback
  }

  function openButton() {
    for (var i = 0; i < drawerButtons.length; i++)
      if (drawerButtons[i] && drawerButtons[i].drawerOpen) return drawerButtons[i]
    return null
  }

  function toggleDrawer() {
    var open = root.openButton()
    if (open) {
      open.dismiss()
      return
    }
    var button = root.focusedDrawerButton()
    if (button) button.open()
  }

  // ------------------------------------------- shell.bar contract (forwarded)

  // Panel hotkeys (`omarchy-shell shell summon omarchy.audio`) route through
  // these. A tucked widget lives in the drawer, so open the drawer and then the
  // widget's own panel from there.
  function summonBarWidget(pluginId) {
    if (root.isTuckedId(pluginId)) {
      var button = root.openButton() || root.focusedDrawerButton()
      return button ? button.openHosted(pluginId) : false
    }
    return bar ? bar.summonBarWidget(pluginId) : false
  }

  function hideBarWidget(pluginId) {
    if (root.isTuckedId(pluginId)) {
      var hidden = false
      for (var i = 0; i < drawerButtons.length; i++)
        if (drawerButtons[i] && drawerButtons[i].closeHosted(pluginId)) hidden = true
      return hidden
    }
    return bar ? bar.hideBarWidget(pluginId) : false
  }

  function isBarWidgetOpen(pluginId) {
    if (root.isTuckedId(pluginId)) {
      for (var i = 0; i < drawerButtons.length; i++)
        if (drawerButtons[i] && drawerButtons[i].hostedOpen(pluginId)) return true
      return false
    }
    return bar ? bar.isBarWidgetOpen(pluginId) : false
  }

  function panelWidgetIdAt(section, index) {
    return bar ? bar.panelWidgetIdAt(section, index) : ""
  }

  function toggleTransparency() {
    if (bar) bar.toggleTransparency()
  }

  function debugBarGeometry() {
    return bar ? bar.debugBarGeometry() : []
  }

  // `omarchy-shell parker.drawer toggle` (also open / close), e.g. for a keybind.
  IpcHandler {
    target: "parker.drawer"

    function toggle(): void {
      root.toggleDrawer()
    }

    function open(): void {
      var button = root.openButton() || root.focusedDrawerButton()
      if (button) button.open()
    }

    function close(): void {
      var button = root.openButton()
      if (button) button.dismiss()
    }
  }
}

import QtQuick
import Quickshell
import qs.Commons
import qs.Ui

// The drawer button and its panel. One instance per monitor, like every bar
// widget. The tucked widgets are created inside the panel once and stay alive
// while it is closed, so their state (update counts, weather, ...) keeps
// ticking and hotkeys can still open their panels.
BarWidget {
  id: root

  // The DrawerBar wrapper; `bar` is the stock Bar.qml root, injected by it.
  property var host: null

  property bool drawerOpen: false
  readonly property bool opened: drawerOpen
  readonly property var entries: host ? host.drawerEntries : []
  readonly property string screenName: {
    var window = root.QsWindow.window
    return window && window.screen ? String(window.screen.name || "") : ""
  }

  // A tucked widget's own panel currently holds the bar's popout slot.
  readonly property bool hostedPopupActive: !!bar && !!bar.activePopout
    && bar.activePopout !== root && ownsTarget(bar.activePopout)

  readonly property string closedIcon: {
    var position = bar ? bar.position : "top"
    if (position === "bottom") return "\uf077"   // chevron-up
    if (position === "left") return "\uf054"     // chevron-right
    if (position === "right") return "\uf053"    // chevron-left
    return "\uf078"                              // chevron-down
  }
  readonly property string openIcon: {
    var position = bar ? bar.position : "top"
    if (position === "bottom") return "\uf078"
    if (position === "left") return "\uf053"
    if (position === "right") return "\uf054"
    return "\uf077"
  }

  visible: entries.length > 0
  implicitWidth: button.implicitWidth
  implicitHeight: button.implicitHeight

  Component.onCompleted: if (host) host.registerDrawerButton(root)
  Component.onDestruction: if (host) host.unregisterDrawerButton(root)

  // ------------------------------------------------------------ popout

  function open() {
    if (!visible) return
    drawerOpen = true
    if (bar && bar.activePopout !== root && !hostedPopupActive) bar.requestPopout(root)
  }

  // Explicit close: the button itself, `omarchy-shell parker.drawer close`.
  function dismiss() {
    closeHostedPopup()
    drawerOpen = false
    if (bar && bar.activePopout === root) bar.releasePopout(root)
  }

  function toggle() {
    if (drawerOpen) dismiss()
    else open()
  }

  // Called by the bar when another popout takes over, and by the panel when its
  // outside-click grab clears. Both also happen when a tucked widget opens its
  // own panel from inside the drawer, which must keep the drawer open as that
  // panel's anchor, so decide once the new owner has settled.
  function close() {
    Qt.callLater(settleClose)
  }

  function closeForPopoutSwitch() {
    Qt.callLater(settleClose)
  }

  function settleClose() {
    if (!drawerOpen || hostedPopupActive) return
    dismiss()
  }

  function closeHostedPopup() {
    var popout = bar ? bar.activePopout : null
    if (!popout || popout === root || !ownsTarget(popout)) return
    if (typeof popout.close === "function") popout.close()
  }

  Connections {
    target: root.bar
    ignoreUnknownSignals: true

    function onActivePopoutChanged() {
      if (!root.drawerOpen) return
      var popout = root.bar.activePopout
      if (popout === root) return
      if (popout === null) {
        // A tucked widget's panel closed; take the popout slot back so opening
        // another bar panel still folds the drawer away.
        Qt.callLater(function() {
          if (root.drawerOpen && root.bar && root.bar.activePopout === null) root.bar.requestPopout(root)
        })
        return
      }
      if (!root.ownsTarget(popout)) root.dismiss()
    }
  }

  // ------------------------------------------------------------ hosting

  // True for anything that lives in this drawer: hosted widgets, their child
  // items, and popups anchored to them.
  function ownsTarget(target) {
    var item = target
    for (var depth = 0; item && depth < 64; depth++) {
      if (item === drawerContent || item === card) return true
      if (item.anchorWindow !== undefined && item.anchorWindow === card) return true
      if (item.anchorItem && item.anchorItem !== item && ownsTarget(item.anchorItem)) return true
      item = item.parent
    }
    return false
  }

  function hostedItems(pluginId) {
    var key = Util.canonicalWidgetId(pluginId)
    var items = []
    for (var i = 0; i < slotRepeater.count; i++) {
      var slot = slotRepeater.itemAt(i)
      if (slot && slot.moduleName === key && slot.activeItem) items.push(slot.activeItem)
    }
    return items
  }

  function hostedOpen(pluginId) {
    var items = hostedItems(pluginId)
    for (var i = 0; i < items.length; i++)
      if (items[i].opened === true) return true
    return false
  }

  function closeHosted(pluginId) {
    var closed = false
    var items = hostedItems(pluginId)
    for (var i = 0; i < items.length; i++) {
      if (items[i].opened === true && typeof items[i].close === "function") {
        items[i].close()
        closed = true
      }
    }
    return closed
  }

  property string pendingHostedId: ""

  // Open the drawer, then the tucked widget's own panel once the drawer window
  // is mapped (a popup cannot anchor to an unmapped window).
  function openHosted(pluginId) {
    var items = hostedItems(pluginId)
    var hasPanel = false
    for (var i = 0; i < items.length; i++)
      if (typeof items[i].open === "function") hasPanel = true
    open()
    if (!hasPanel) return items.length > 0
    pendingHostedId = Util.canonicalWidgetId(pluginId)
    hostedOpenTimer.restart()
    return true
  }

  Timer {
    id: hostedOpenTimer
    interval: 60
    onTriggered: {
      var items = root.hostedItems(root.pendingHostedId)
      root.pendingHostedId = ""
      for (var i = 0; i < items.length; i++) {
        if (typeof items[i].open === "function") {
          items[i].open()
          return
        }
      }
    }
  }

  // ------------------------------------------------------------ visuals

  BarIconButton {
    id: button
    anchors.fill: parent
    bar: root.bar
    text: root.drawerOpen
